'use strict';
const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');
const url = 'http://localhost:6006/iframe.html?id=commerce-productitem--with-warning-message&viewMode=story';
async function waitReady(page) {
  await page.waitForFunction(() => document.querySelector('#storybook-root')?.children.length > 0, { timeout: 15000 });
  await page.waitForTimeout(300);
}
async function main() {
  const browser = await chromium.launch({ headless: true });
  for (let run = 1; run <= 3; run++) {
    console.log(`\n=== RE-VERIFY RUN ${run} ===`);
    const page = await browser.newPage();
    await page.goto(url, { waitUntil: 'domcontentloaded' });
    await waitReady(page);
    const statusLocator = page.locator('[role="status"]');
    const inputLocator = page.locator('input').first();
    const readState = async () => ({
      value: await inputLocator.inputValue(),
      status: await statusLocator.first().evaluate((el) => el.textContent),
    });
    console.log('before:', JSON.stringify(await readState()));
    const incButton = page.getByRole('button', { name: /Increment Quantity/i });
    await incButton.click();
    await page.waitForTimeout(300);
    console.log('after increment click:', JSON.stringify(await readState()));
    const decButton = page.getByRole('button', { name: /Decrement Quantity/i });
    try {
      await decButton.click({ timeout: 5000 });
      await page.waitForTimeout(300);
      console.log('after decrement click: SUCCESS', JSON.stringify(await readState()));
    } catch (err) {
      console.log('after decrement click: FAILED —', String(err).split('\n')[0]);
      const raw = await page.evaluate(() => {
        const d = document.querySelector('[data-testid="quantity-decrement"]');
        return d ? d.outerHTML : 'NOT FOUND';
      });
      console.log('direct DOM read of decrement button at failure time:', raw);
    }
    await page.close();
  }
  await browser.close();
}
main().catch(e => { console.error('FATAL', e); process.exit(1); });

