'use strict';
/**
 * Ad hoc proof script (NOT part of the configured E2E suite, not run through any Playwright
 * config/test-runner). Proves that ZimmQuantityStepper's aria-live="polite" span genuinely
 * updates the SAME DOM node's textContent after a real click on the real, unmocked
 * useDerivedProduct-backed ProductItem story, as opposed to merely carrying the aria-live
 * attribute in static markup (the old, already-fixed bug: attribute present, text never
 * re-rendered).
 *
 * Run with plain node from the project root:
 *   node <this file>
 */
const { chromium } = require('playwright-core');

const URL = 'http://localhost:6006/iframe.html?id=commerce-productitem--default&viewMode=story';
const PROOF_MARKER = 'sfcc271-liveregion-proof';

/**
 * Polls the SAME ElementHandle's textContent (never re-queries the DOM) until it matches
 * `expected` or times out. Because this calls `.evaluate()` repeatedly on one persistent
 * handle, a false pass here would require the same remote object reference to report the new
 * text — it cannot be satisfied by a different node quietly replacing the old one at the same
 * screen position.
 */
async function waitForHandleText(handle, expected, timeoutMs = 5000, intervalMs = 50) {
  const start = Date.now();
  let last;
  while (Date.now() - start < timeoutMs) {
    last = await handle.evaluate((el) => el.textContent);
    if (last != null && last.trim() === expected) return last;
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
  throw new Error(`Timed out waiting for handle text to become "${expected}" — last observed "${last}"`);
}

async function main() {
  const consoleMessages = [];
  const pageErrors = [];
  const results = {};

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  page.on('console', (msg) => {
    consoleMessages.push(`[${msg.type()}] ${msg.text()}`);
  });
  page.on('pageerror', (err) => {
    pageErrors.push(String(err && err.stack ? err.stack : err));
  });

  await page.goto(URL, { waitUntil: 'domcontentloaded' });

  // Wait for Storybook to actually mount the story into #storybook-root.
  await page.waitForFunction(
    () => {
      const root = document.querySelector('#storybook-root');
      return !!root && root.children.length > 0;
    },
    undefined,
    { timeout: 15000 },
  );

  // Sanity: exactly one live-region value span should exist (Default story renders one
  // ProductItem, not MultipleItems).
  results.liveRegionSpanCount = await page.locator('span[aria-live="polite"]').count();

  const valueLocator = page.locator('span[aria-live="polite"]').first();
  await valueLocator.waitFor({ state: 'visible', timeout: 10000 });

  // Persistent handle to the exact DOM node — every read below re-uses this same handle
  // rather than re-querying the selector, so a before/after diff on it can only mean the
  // node's own text actually changed.
  const valueHandle = await valueLocator.elementHandle();
  if (!valueHandle) {
    throw new Error('Could not obtain an elementHandle for span[aria-live="polite"]');
  }

  // Tag the physical node so a later fresh query can be checked for referential identity
  // against this same handle (proves "no swap", not just "text matches").
  await valueHandle.evaluate((el, marker) => el.setAttribute('data-proof-marker', marker), PROOF_MARKER);

  results.ariaLiveAttr = await valueHandle.evaluate((el) => el.getAttribute('aria-live'));

  const readSameNode = () => valueHandle.evaluate((el) => el.textContent);
  const isAttached = () => valueHandle.evaluate((el) => document.contains(el));

  const incrementBtn = page.getByRole('button', { name: 'Increase quantity' });
  const decrementBtn = page.getByRole('button', { name: 'Decrease quantity' });

  results.incrementBtnCount = await incrementBtn.count();
  results.decrementBtnCount = await decrementBtn.count();

  // --- Step 3: BEFORE any interaction ---
  results.before = await readSameNode();
  results.beforeAttached = await isAttached();

  // --- Step 4/5: click increment once, 1 -> 2 ---
  await incrementBtn.click();
  results.afterClick1 = await waitForHandleText(valueHandle, '2');
  results.afterClick1Attached = await isAttached();

  // --- Step 6: click increment again, 2 -> 3 ---
  await incrementBtn.click();
  results.afterClick2 = await waitForHandleText(valueHandle, '3');
  results.incrementAriaDisabledAtCap = await incrementBtn.getAttribute('aria-disabled');

  // --- Step 6 continued: click increment a third time at the cap — expect NO change ---
  await incrementBtn.click();
  // No positive condition to poll for (we're proving absence of change), so a short explicit
  // wait here is intentional, not a substitute for the polling used everywhere else above.
  await page.waitForTimeout(500);
  results.afterClick3AtCap = await readSameNode();
  results.incrementAriaDisabledAfterClick3 = await incrementBtn.getAttribute('aria-disabled');

  // --- Step 7: click decrement once, 3 -> 2 ---
  await decrementBtn.click();
  results.afterDecrement = await waitForHandleText(valueHandle, '2');

