'use strict';
const { chromium } = require(
  require.resolve('playwright-core', { paths: ['/Users/marcel.a.n.navarro/Dev/zimmermann-pwa'] }),
);
const URL = 'http://localhost:6006/iframe.html?id=commerce-productitem--default&viewMode=story';

async function dumpState(page, label) {
  const info = await page.evaluate(() => {
    const btns = Array.from(document.querySelectorAll('button[aria-label]'));
    const spans = Array.from(document.querySelectorAll('span[aria-live="polite"]'));
    return {
      buttons: btns.map((b) => ({ label: b.getAttribute('aria-label'), disabled: b.getAttribute('aria-disabled') })),
      digitSpans: spans.filter((s) => /^\s*\d+\s*$/.test(s.textContent)).map((s) => s.textContent),
    };
  });
  console.log(`[${label}]`, JSON.stringify(info));
}

async function main() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.on('pageerror', (e) => console.log('  [browser pageerror]', String(e)));

  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(
    () => {
      const root = document.querySelector('#storybook-root');
      return !!root && root.children.length > 0;
    },
    undefined,
    { timeout: 15000 },
  );
  await dumpState(page, 'mounted');

  const valueLocator = page.locator('span[aria-live="polite"]').filter({ hasText: /^\s*\d+\s*$/ });
  await valueLocator.waitFor({ state: 'attached', timeout: 10000 });
  const valueHandle = await valueLocator.elementHandle();
  await valueHandle.evaluate((el, marker) => el.setAttribute('data-proof-marker', marker), 'sfcc271-liveregion-proof');
  await dumpState(page, 'after-marker-set');

  const incrementBtn = page.getByRole('button', { name: 'Increase quantity' });
  await dumpState(page, 'before-click-attempt');

  try {
    await incrementBtn.click({ timeout: 3000 });
    console.log('CLICK SUCCEEDED');
  } catch (e) {
    console.log('CLICK FAILED:', String(e).split('\n')[0]);
  }
  await dumpState(page, 'after-click-attempt');

  // try clicking via raw DOM dispatch to see if the click handler itself works when bypassing
  // Playwright's actionability gate
  await page.evaluate(() => {
    const btn = Array.from(document.querySelectorAll('button[aria-label]')).find(
      (b) => b.getAttribute('aria-label') === 'Increase quantity',
    );
    btn.click();
  });
  await dumpState(page, 'after-raw-dom-click');

