// would resolve relative to this file's own location, not the project root, and fail. Resolve
// explicitly against the project root's node_modules instead (still the project's installed
// playwright-core — same package the task confirmed is resolvable from that cwd).
const { chromium } = require(
  require.resolve('playwright-core', { paths: ['/Users/marcel.a.n.navarro/Dev/zimmermann-pwa'] }),
);

const URL = 'http://localhost:6006/iframe.html?id=commerce-productitem--default&viewMode=story';
const PROOF_MARKER = 'sfcc271-liveregion-proof';

/**
 * Polls the SAME ElementHandle's textContent (never re-queries the DOM) until it matches
 * `expected` or times out. Because this calls `.evaluate()` repeatedly on one persistent
 * handle, a false pass here would require the same remote object reference to report the new
 * text — it cannot be satisfied by a different node quietly replacing the old one at the same
 * screen position.
 */
async function waitForHandleText(handle, expected, timeoutMs = 5000, intervalMs = 50) {
  const start = Date.now();
  let last;
  while (Date.now() - start < timeoutMs) {
    last = await handle.evaluate((el) => el.textContent);
    if (last != null && last.trim() === expected) return last;
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
