}

async function main() {
  const consoleMessages = [];
  const pageErrors = [];
  const results = {};

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  page.on('console', (msg) => {
    consoleMessages.push(`[${msg.type()}] ${msg.text()}`);
  });
  page.on('pageerror', (err) => {
    pageErrors.push(String(err && err.stack ? err.stack : err));
  });

  await page.goto(URL, { waitUntil: 'domcontentloaded' });

  // Wait for Storybook to actually mount the story into #storybook-root.
  await page.waitForFunction(
    () => {
      const root = document.querySelector('#storybook-root');
      return !!root && root.children.length > 0;
    },
    undefined,
    { timeout: 15000 },
  );
  // Settle wait: two ad hoc runs of this exact script during development observed the
  // increment button transiently rendering `aria-disabled="true"` at initial mount (quantity
  // 1, well under the max of 3) for several seconds before settling — reproducible twice, then
  // NOT reproducible on later runs or in a simplified bisection script, so this looks like a
  // dev-mode (webpack/React) mount race rather than something caused by this script's own
  // read-only queries (a step-by-step bisection confirmed the state was already correct before
  // any of this script's own DOM reads). Recorded as `results.incrementAriaDisabledAtMount`
  // below regardless, so a recurrence is visible in the output rather than silently waited out.
  await page.waitForTimeout(300);

  // Diagnostic finding (confirmed by a throwaway probe before this script was finalised): the
  // page actually has THREE span[aria-live="polite"] elements, not one — two are
  // CartItemVariantPrice's visually-hidden sr-only "current price" announcements (rendered
  // twice, once each for HideOnMobile/HideOnDesktop, both `aria-atomic="true"`, hidden per
  // Playwright's visibility check), and only one is ZimmQuantityStepper's own value span (no
  // `aria-atomic` attribute, per its source at
  // overrides/app/components/ui-kits/molecules/zimmQuantityStepper/index.tsx). Filtering to
  // whole-text-is-digits uniquely isolates the quantity span from the two price spans, whose
  // text is a product name + currency string, not exact digits.
