'use strict';
/**
 * Ad hoc proof script (NOT part of the configured E2E suite, not run through any Playwright
 * config/test-runner). Proves that ZimmQuantityStepper's aria-live="polite" span genuinely
 * updates the SAME DOM node's textContent after a real click on the real, unmocked
 * useDerivedProduct-backed ProductItem story, as opposed to merely carrying the aria-live
 * attribute in static markup (the old, already-fixed bug: attribute present, text never
 * re-rendered).
 *
 * Run with plain node from the project root:
 *   node <this file>
 */
const { chromium } = require(
  require.resolve('playwright-core', { paths: ['/Users/marcel.a.n.navarro/Dev/zimmermann-pwa'] }),
);

const URL = 'http://localhost:6006/iframe.html?id=commerce-productitem--default&viewMode=story';
const PROOF_MARKER = 'sfcc271-liveregion-proof';

const results = {};
const consoleMessages = [];
const pageErrors = [];

function log(step, value) {
  results[step] = value;
  console.log(`[${step}]`, JSON.stringify(value));
}

async function waitForHandleText(handle, expected, timeoutMs = 8000, intervalMs = 50) {
  const start = Date.now();
  let last;
  while (Date.now() - start < timeoutMs) {
    last = await handle.evaluate((el) => el.textContent);
    if (last != null && last.trim() === expected) return last;
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
  throw new Error(`Timed out waiting for handle text to become "${expected}" — last observed "${last}"`);
}

async function main() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  page.on('console', (msg) => consoleMessages.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => pageErrors.push(String(err && err.stack ? err.stack : err)));

  try {
    await page.goto(URL, { waitUntil: 'domcontentloaded' });

    await page.waitForFunction(
      () => {
        const root = document.querySelector('#storybook-root');
        return !!root && root.children.length > 0;
      },
      undefined,
      { timeout: 15000 },
    );
    await page.waitForTimeout(300);

    log('allAriaLiveSpanCount', await page.locator('span[aria-live="polite"]').count());

    const valueLocator = page.locator('span[aria-live="polite"]').filter({ hasText: /^\s*\d+\s*$/ });
    log('quantitySpanMatchCount', await valueLocator.count());
    if (results.quantitySpanMatchCount !== 1) {
      throw new Error(`Expected exactly 1 digit-only span[aria-live="polite"], found ${results.quantitySpanMatchCount}`);
    }
    await valueLocator.waitFor({ state: 'attached', timeout: 10000 });

    const valueHandle = await valueLocator.elementHandle();
    if (!valueHandle) throw new Error('Could not obtain an elementHandle for span[aria-live="polite"]');

    await valueHandle.evaluate((el, marker) => el.setAttribute('data-proof-marker', marker), PROOF_MARKER);
    log('ariaLiveAttr', await valueHandle.evaluate((el) => el.getAttribute('aria-live')));

    const readSameNode = () => valueHandle.evaluate((el) => el.textContent);
    const isAttached = () => valueHandle.evaluate((el) => document.contains(el));

    const incrementBtn = page.getByRole('button', { name: 'Increase quantity' });
    const decrementBtn = page.getByRole('button', { name: 'Decrease quantity' });

    log('incrementBtnCount', await incrementBtn.count());
    log('decrementBtnCount', await decrementBtn.count());
    log('incrementAriaDisabledAtMount', await incrementBtn.getAttribute('aria-disabled'));
    log('decrementAriaDisabledAtMount', await decrementBtn.getAttribute('aria-disabled'));

    log('before', await readSameNode());
    log('beforeAttached', await isAttached());

    if (results.incrementAriaDisabledAtMount === 'true') {
      // Observed intermittently during development (see report) — not silently retried away.
      // Give it one bounded extra settle window and re-read before deciding whether to proceed;
      // if it's still disabled, fail loudly rather than hang on the click's own 30s timeout.
      console.log('WARNING: increment already aria-disabled at mount with quantity', results.before, '— waiting up to 5s for it to clear...');
      try {
        await page.waitForFunction(
          () => {
            const btn = document.querySelector('button[aria-label="Increase quantity"]');
            return btn && btn.getAttribute('aria-disabled') !== 'true';
          },
          undefined,
          { timeout: 5000 },
        );
        log('incrementAriaDisabledRecoveredAfterWait', await incrementBtn.getAttribute('aria-disabled'));
      } catch (e) {
        log('incrementAriaDisabledRecoveredAfterWait', 'NEVER RECOVERED WITHIN 5s');
      }
    }

    // --- click 1: 1 -> 2 ---
    await incrementBtn.click({ timeout: 8000 });
    log('afterClick1', await waitForHandleText(valueHandle, '2'));
    log('afterClick1Attached', await isAttached());

    // --- click 2: 2 -> 3 ---
    await incrementBtn.click({ timeout: 8000 });
    log('afterClick2', await waitForHandleText(valueHandle, '3'));
    log('incrementAriaDisabledAtCap', await incrementBtn.getAttribute('aria-disabled'));

    // --- click 3 at cap: expect NO change ---
    await page.evaluate(() => {
      // raw dispatch, bypasses Playwright's actionability gate on purpose: we WANT to prove
      // the component's own internal guard (handleIncrement's `if (incrementInert) return`)
      // is what stops it, not merely that Playwright refused to click a disabled-looking node.
      const btn = document.querySelector('button[aria-label="Increase quantity"]');
      btn.click();
    });
    await page.waitForTimeout(500);
    log('afterClick3AtCap', await readSameNode());
    log('incrementAriaDisabledAfterClick3', await incrementBtn.getAttribute('aria-disabled'));

    // --- decrement once: 3 -> 2 ---
    await decrementBtn.click({ timeout: 8000 });
    log('afterDecrement', await waitForHandleText(valueHandle, '2'));

    const freshHandle = await page.locator('span[aria-live="polite"]').filter({ hasText: /^\s*\d+\s*$/ }).elementHandle();
    log('sameNodeConfirmedViaFreshQuery', await page.evaluate(([a, b]) => a === b, [valueHandle, freshHandle]));
    log('freshQueryMarkerMatches', (await freshHandle.evaluate((el) => el.getAttribute('data-proof-marker'))) === PROOF_MARKER);
    log('finalAttached', await isAttached());
  } finally {
    await browser.close();
  }
}

main()
  .then(() => {
    console.log('=== FINAL RESULTS ===');
    console.log(JSON.stringify(results, null, 2));
    console.log('=== CONSOLE MESSAGES ===');
    console.log(consoleMessages.length ? consoleMessages.join('\n') : '(none)');
    console.log('=== PAGE ERRORS ===');
    console.log(pageErrors.length ? pageErrors.join('\n') : '(none)');
  })
  .catch((e) => {
    console.error('FATAL', e);
    console.log('=== PARTIAL RESULTS BEFORE FAILURE ===');
    console.log(JSON.stringify(results, null, 2));
    console.log('=== CONSOLE MESSAGES ===');
    console.log(consoleMessages.length ? consoleMessages.join('\n') : '(none)');
    console.log('=== PAGE ERRORS ===');
    console.log(pageErrors.length ? pageErrors.join('\n') : '(none)');
    process.exit(1);
  });

