  // wait here is intentional, not a substitute for the polling used everywhere else above.
  await page.waitForTimeout(500);
  results.afterClick3AtCap = await readSameNode();
  results.incrementAriaDisabledAfterClick3 = await incrementBtn.getAttribute('aria-disabled');

  // --- Step 7: click decrement once, 3 -> 2 ---
  await decrementBtn.click();
  results.afterDecrement = await waitForHandleText(valueHandle, '2');

  // --- Final identity re-check: a FRESH query for the same selector must resolve to the
  // exact same node the whole test has been reading from. ---
  const freshHandle = await page.locator('span[aria-live="polite"]').first().elementHandle();
  results.sameNodeConfirmedViaFreshQuery = await page.evaluate(
    ([a, b]) => a === b,
    [valueHandle, freshHandle],
  );
  results.freshQueryMarkerMatches =
    (await freshHandle.evaluate((el) => el.getAttribute('data-proof-marker'))) === PROOF_MARKER;
  results.finalAttached = await isAttached();

  await browser.close();

  console.log('=== RESULTS ===');
  console.log(JSON.stringify(results, null, 2));
  console.log('=== CONSOLE MESSAGES ===');
  console.log(consoleMessages.length ? consoleMessages.join('\n') : '(none)');
  console.log('=== PAGE ERRORS ===');
  console.log(pageErrors.length ? pageErrors.join('\n') : '(none)');
}

main().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});
